// Generated by gstack /ship Step 7 coverage audit for PR #14 (pass 1).
// Value cards, one per test, are in the comment above each test.
import { afterAll, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, readdirSync, realpathSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { approvalsBin } from "../../src/runner/ledger/approvals.ts";
import { ledgerCli } from "../../src/runner/ledger/cli.ts";
import { importSettlement, openLease, recordApproval } from "../../src/runner/ledger/ledger.ts";
import { remoteMount } from "../../src/runner/ledger/paths.ts";
import { LedgerError, readItem } from "../../src/runner/ledger/record.ts";

const dirs: string[] = [];
afterAll(() => dirs.forEach((d) => rmSync(d, { recursive: true, force: true })));
const scratch = () => {
  const d = mkdtempSync(join(tmpdir(), "ledger-cli-edges-"));
  dirs.push(d);
  return d;
};
const quote = { words: "Rec", by: "Garry Tan", source: "gate 1" };

function codeOf(fn: () => unknown): string {
  try {
    fn();
  } catch (error) {
    if (error instanceof LedgerError) return error.code;
    throw error;
  }
  return "ok";
}

describe("ledger CLI and import edges", () => {
  // Value: protects=a settle artifact can only close the lease it names as settled; fails_when=importSettlement drops its kind, how, item or slot check; why_new=the round trip imports only a matching artifact; seam=none; no_claim=none beyond protects
  test("importSettlement refuses an artifact that is not a settled close of the lease it names, and writes nothing", () => {
    const record = join(scratch(), "record");
    recordApproval(record, { action: "init", item: "lanea", cap_micros: 5_000_000, quotes: [quote], admission: "warn" });
    const lease = openLease(record, null, { item: "lanea", run_id: "sealed-1", machine_id: "workflow:sealed", amount_micros: 1_000_000 });
    const close = { schema: 1, kind: "close", item: "lanea", seq: 1, lease_id: lease.lease_id, how: "settled", spent_micros: 0, unknown_micros: 0, unknown_calls: 0, usage: null, closed_at: "2026-10-28T00:00:00.000Z" };
    for (const bad of [{ ...close, how: "reconciled" }, { ...close, seq: 2 }, { ...close, kind: "lease" }, null]) expect(codeOf(() => importSettlement(record, bad))).toBe("E_USAGE");
    expect(codeOf(() => importSettlement(record, { ...close, lease_id: "lanea.0009.abcdef" }))).toBe("E_LEASE_UNSETTLED");
    expect(readdirSync(join(record, "items", "lanea")).sort()).toEqual(["approval-0001.json", "lease-0001.json"]);
  });

  // Value: protects=bad lease and reconcile flags are E_USAGE before anything is leased; fails_when=a --ttl, --machine, repeated-flag or --source guard is dropped; why_new=cli.test.ts feeds only init usage mistakes; seam=none; no_claim=none beyond protects
  test("bad lease and reconcile flags are E_USAGE and lease nothing", async () => {
    const dir = scratch();
    const env = { GSTACK_EVALS_LEDGER_RECORD: join(dir, "record"), GSTACK_EVALS_LEDGER: join(dir, "ledger.sqlite"), PATH: "" };
    const cli = async (...argv: string[]) => {
      const err: string[] = [];
      const code = await ledgerCli(argv, { out: () => {}, err: (s) => err.push(s) }, env);
      return { code, err: err.join("\n") };
    };
    recordApproval(env.GSTACK_EVALS_LEDGER_RECORD, { action: "init", item: "lanea", cap_micros: 5_000_000, quotes: [quote], admission: "warn" });
    for (const argv of [
      ["lease", "--item", "lanea", "--run", "r", "--ttl", "0"],
      ["lease", "--item", "lanea", "--run", "r", "--ttl", "abc"],
      ["lease", "--item", "lanea", "--run", "r", "--ttl", "169"],
      ["lease", "--item", "lanea", "--run", "r", "--machine", "workflow:sealed"],
      ["lease", "--item", "lanea", "--item", "lanea", "--run", "r"],
      ["reconcile", "--lease", "lanea.0001.abcdef", "--spent", "1", "--words", "w", "--by", "b", "--source", "a.csv", "--source", "b.csv"],
    ]) {
      const r = await cli(...argv);
      expect(r.code).toBe(2);
      expect(r.err.split("\n").every((line) => line.startsWith("E_USAGE "))).toBe(true);
    }
    expect(readItem(env.GSTACK_EVALS_LEDGER_RECORD, "lanea").leases).toEqual([]);
  });

  // Value: protects=the FUSE refusal follows symlinks and does not match a sibling whose name shares a prefix; fails_when=remoteMount drops realpath or the trailing-slash prefix check; why_new=paths.test.ts uses direct paths only; seam=none; no_claim=readMounts parsing of /proc/self/mounts
  test("remoteMount follows a symlink into a FUSE mount and ignores a sibling that only shares a prefix", () => {
    const dir = realpathSync(scratch());
    const fuse = join(dir, "drive");
    mkdirSync(fuse);
    mkdirSync(join(dir, "drivex"));
    symlinkSync(fuse, join(dir, "link"));
    const mounts = [{ point: "/", type: "ext4" }, { point: fuse, type: "fuse.capydrive" }];
    expect(remoteMount(join(dir, "link", "ledger.sqlite"), mounts)).toBe("fuse.capydrive");
    expect(remoteMount(join(dir, "drivex", "ledger.sqlite"), mounts)).toBeNull();
  });

  // Value: protects=gstack-approvals is found by override, then PATH order; fails_when=the override or PATH search breaks, so init fails as not found; why_new=cli.test.ts always sets the override; seam=none; no_claim=the ~/.local/share/gstack default (uses the real home)
  test("approvalsBin takes the override first, then the first gstack-approvals on PATH", () => {
    const a = scratch();
    const b = scratch();
    writeFileSync(join(b, "gstack-approvals"), "#!/bin/sh\n", { mode: 0o755 });
    expect(approvalsBin({ PATH: a + ":" + b })).toBe(join(b, "gstack-approvals"));
    expect(approvalsBin({ PATH: a + ":" + b, GSTACK_EVALS_APPROVALS_BIN: "/opt/x/gstack-approvals" })).toBe("/opt/x/gstack-approvals");
  });
});
